window.CHAPTERS = [{"number": 1, "title": "Unit 1 · Pathway 1 · Intro to Programming", "questions": [{"id": "google-u1-p1-q1", "text": "Which of the following variable declarations is valid?", "type": "single", "options": [{"id": "A", "text": "var hello: Int? = \"\""}, {"id": "B", "text": "String \"hello\" = hello"}, {"id": "C", "text": "val hello = \"hello\""}, {"id": "D", "text": "hello: String = \"hello\""}], "answers": ["C"], "plain": true, "note": "", "explanation": "Khai báo cần có val hoặc var; Kotlin có thể suy ra kiểu từ vế phải. Ví dụ val hello = \"hello\" là String, còn var hello: Int? = \"\" sai vì gán chuỗi cho kiểu số nguyên nullable.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q2", "text": "It is considered best practice to declare a variable that will not change using var instead of val .", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Dùng val khi không cần gán lại để thể hiện ý định và giảm lỗi sửa biến ngoài dự kiến. val không làm đối tượng mutable trở thành immutable; nó chỉ ngăn đổi tham chiếu bằng phép gán.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q3", "text": "Which of the following are valid ways to update a variable?", "type": "multi", "options": [{"id": "A", "text": "total++"}, {"id": "B", "text": "total - 1"}, {"id": "C", "text": "total--"}, {"id": "D", "text": "total = total + 1"}], "answers": ["A", "C", "D"], "plain": true, "note": "", "explanation": "Giả sử total là var kiểu số: total++ và total-- cập nhật biến, còn total = total + 1 gán giá trị mới. Biểu thức total - 1 chỉ tính một kết quả rồi bỏ đi nếu không sử dụng hoặc gán lại.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q4", "text": "In Kotlin, comments can be single or multi-line and are ignored by the compiler.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "// ghi chú đến hết dòng; /* ... */ có thể trải trên nhiều dòng và Kotlin còn hỗ trợ comment khối lồng nhau. Comment giúp giải thích ý định nhưng không trở thành câu lệnh được thực thi.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q5", "text": "Which of the following is not a data type in Kotlin?", "type": "single", "options": [{"id": "A", "text": "String"}, {"id": "B", "text": "Decimal"}, {"id": "C", "text": "Int"}, {"id": "D", "text": "Boolean"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Các kiểu số dựng sẵn gồm Byte, Short, Int, Long, Float, Double; Decimal không phải tên kiểu dựng sẵn. Nếu cần tính thập phân chính xác cho tiền tệ trên JVM có thể cân nhắc BigDecimal thay vì số thực nhị phân.", "references": [{"url": "https://kotlinlang.org/docs/numbers.html", "title": "Kotlin · Kiểu số"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q6", "text": "Float also represents a decimal, but is less precise than Double .", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Float dùng 32 bit còn Double dùng 64 bit, nên Float thường chỉ giữ khoảng 6–7 chữ số thập phân có nghĩa so với khoảng 15–16 của Double. Literal 3.14 mặc định là Double; 3.14f là Float.", "references": [{"url": "https://kotlinlang.org/docs/numbers.html", "title": "Kotlin · Kiểu số"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q7", "text": "In Kotlin, the entrypoint of a program is the ___.", "type": "single", "options": [{"id": "A", "text": "println() statement"}, {"id": "B", "text": "val variable"}, {"id": "C", "text": "main() function"}, {"id": "D", "text": "return statement"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Một chương trình Kotlin thông thường bắt đầu ở fun main() hoặc main(args: Array<String>). println chỉ là lời gọi in dữ liệu. Riêng ứng dụng Android có các điểm vào do framework quản lý, không viết main() làm Activity entrypoint.", "references": [{"url": "https://kotlinlang.org/docs/basic-syntax.html", "title": "Kotlin · Cú pháp cơ bản"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q8", "text": "Which of the following are true about function return values?", "type": "multi", "options": [{"id": "A", "text": "If a function does not specify a return type, the return type is Unit ."}, {"id": "B", "text": "A return value can be stored in a variable."}, {"id": "C", "text": "Functions with a return type of Unit must include a return statement."}, {"id": "D", "text": "A return value's type must match the return type of a function."}], "answers": ["A", "B", "D"], "plain": true, "note": "", "explanation": "Ý “không khai báo kiểu trả về thì dùng Unit” của Google dùng ngữ cảnh hàm thân khối nhập môn, không phải quy tắc cho mọi hàm. Với fun twice(x: Int) = x * 2, Kotlin suy ra Int. Hàm Unit không bắt buộc viết return; giá trị trả về thông thường có thể được gán cho biến và phải đúng kiểu khai báo.", "references": [{"url": "https://kotlinlang.org/docs/functions.html", "title": "Kotlin · Hàm"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q9", "text": "Which of the following are true about functions?", "type": "multi", "options": [{"id": "A", "text": "Functions can take parameters, or variables as inputs."}, {"id": "B", "text": "Function parameters are required to have default arguments."}, {"id": "C", "text": "When calling a function with parameters, the values passed in are called arguments."}, {"id": "D", "text": "Breaking up your code into separate functions makes your code easier to maintain."}], "answers": ["A", "C", "D"], "plain": true, "note": "", "explanation": "Parameter nằm trong khai báo hàm; argument là giá trị truyền ở lời gọi, như name trong fun greet(name: String) và \"Lan\" trong greet(\"Lan\"). Giá trị mặc định là tùy chọn. Chia nhỏ hàm theo trách nhiệm giúp đọc, kiểm thử và bảo trì.", "references": [{"url": "https://kotlinlang.org/docs/functions.html", "title": "Kotlin · Hàm"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p1-q10", "text": "With named arguments, you can change the order in which you pass arguments into a function.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Khi gọi greet(age = 20, name = \"Lan\"), tên argument cho biết nó đi vào tham số nào nên thứ tự có thể thay đổi. Nếu trộn positional và named argument cần tuân thủ quy tắc Kotlin; tên phải khớp khai báo hàm.", "references": [{"url": "https://kotlinlang.org/docs/functions.html", "title": "Kotlin · Hàm"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-1/android-basics-compose-unit-1-pathway-1?hl=en", "title": "Google · Unit 1 · Pathway 1 · Đáp án đã kiểm chứng"}}]}, {"number": 2, "title": "Unit 1 · Pathway 2 · Set up Android Studio", "questions": [{"id": "google-u1-p2-q1", "text": "What does IDE stand for?", "type": "single", "options": [{"id": "A", "text": "Integrated Development Environment"}, {"id": "B", "text": "Independent Design Environment"}, {"id": "C", "text": "Ideal Developer Environment"}, {"id": "D", "text": "Intelligent Design Environment"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Integrated Development Environment là môi trường tích hợp sửa mã, điều hướng, build và debug. Android Studio là một IDE; Gradle là hệ thống build mà IDE dùng, không phải cùng một khái niệm.", "references": [{"url": "https://developer.android.com/studio/intro", "title": "Android Studio"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q2", "text": "Which of the following are advantages of using Android Studio?", "type": "multi", "options": [{"id": "A", "text": "It can help prevent typos and other mistakes in your code."}, {"id": "B", "text": "It comes with a virtual device called an emulator that can run your app."}, {"id": "C", "text": "It can show you a real-time preview of how your app will look on-screen while you code."}, {"id": "D", "text": "It can automatically translate your app into other languages."}], "answers": ["A", "B", "C"], "plain": true, "note": "", "explanation": "Code inspection và gợi ý hoàn thành giúp giảm lỗi; emulator hỗ trợ chạy thử; Compose Preview hỗ trợ xem UI. Android Studio không mặc nhiên dịch toàn bộ giao diện sang ngôn ngữ khác: lập trình viên vẫn cần quản lý tài nguyên bản dịch.", "references": [{"url": "https://developer.android.com/studio/intro", "title": "Android Studio"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q3", "text": "What is the purpose of using a virtual device, or emulator, in Android Studio?", "type": "single", "options": [{"id": "A", "text": "To show a variety of error messages to users"}, {"id": "B", "text": "To experiment with app code safely"}, {"id": "C", "text": "To test your app on a device without having that physical device"}, {"id": "D", "text": "To see what your app looks like in a web browser"}], "answers": ["C"], "plain": true, "note": "", "explanation": "AVD mô phỏng cấu hình máy, API Android và kích thước màn hình để cài/chạy ứng dụng. Nó không phải trình duyệt web và không thay thế hoàn toàn thử nghiệm thực tế về hiệu năng, cảm biến hay phần cứng.", "references": [{"url": "https://developer.android.com/studio/run/emulator", "title": "Android Emulator"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q4", "text": "In Android Studio, what is a project template good for?", "type": "multi", "options": [{"id": "A", "text": "It causes Android Studio to download files faster."}, {"id": "B", "text": "It makes getting started on building a new app faster."}, {"id": "C", "text": "It provides a structure that follows best practices."}, {"id": "D", "text": "It is the only way to build apps that can be previewed in Android Studio."}, {"id": "E", "text": "It makes building a new app less error-prone by pre-populating the project with some app code."}], "answers": ["B", "C", "E"], "plain": true, "note": "", "explanation": "Template sinh cấu trúc module, cấu hình build và mã mẫu để bắt đầu nhanh hơn, ít thiếu bước hơn. Nó không phải cách duy nhất để viết ứng dụng hoặc tạo preview; dự án có sẵn vẫn có thể thêm composable và @Preview.", "references": [{"url": "https://developer.android.com/studio/projects/create-project", "title": "Tạo dự án Android"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q5", "text": "How do you create a new project in Android Studio?", "type": "single", "options": [{"id": "A", "text": "A. Log out of Android Studio, and navigate to your project folder to find instructions."}, {"id": "B", "text": "B. If you have a project already open, select File > New > New Project from the Android Studio menu."}, {"id": "C", "text": "C. In the “Welcome to Android Studio” window, click “Start a new Android Studio project.”"}, {"id": "D", "text": "D. Create a new file on your computer, and title it “New Android Studio Project.\""}, {"id": "E", "text": "Both B and C are ways to create a new project in Android Studio."}, {"id": "F", "text": "None of the above"}], "answers": ["E"], "plain": true, "note": "", "explanation": "Có thể tạo dự án từ File → New → New Project khi đang mở IDE hoặc từ nút New Project ở màn hình Welcome. Nhãn nút có thể thay đổi theo bản Android Studio. Chỉ tạo một file tên “New Android Studio Project” không tạo ra dự án Android hợp lệ.", "references": [{"url": "https://developer.android.com/studio/projects/create-project", "title": "Tạo dự án Android"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q6", "text": "___ is a function that is used to define a layout in your app using Composable functions.", "type": "single", "options": [{"id": "A", "text": "ComponentActivity()"}, {"id": "B", "text": "onCreate()"}, {"id": "C", "text": "DefaultPreview()"}, {"id": "D", "text": "setContent()"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Trong ComponentActivity, setContent { ... } đặt nội dung UI Compose cho Activity. onCreate là callback vòng đời thường chứa lời gọi này, còn @Preview chỉ phục vụ công cụ xem trước. ComponentActivity là lớp, không phải hàm dựng nội dung thay cho setContent.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q7", "text": "A Compose function requires the @Composable annotation.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "@Composable đánh dấu hàm tham gia mô tả UI trong hệ Compose. Hàm có thể được chạy lại khi dữ liệu liên quan thay đổi, vì vậy không nên coi nó là lệnh vẽ chỉ chạy một lần. @Preview có vai trò khác và không thay thế @Composable.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q8", "text": "A ___ is a Composable that has a background color and can contain other Composables.", "type": "single", "options": [{"id": "A", "text": "Color"}, {"id": "B", "text": "Container"}, {"id": "C", "text": "Surface"}, {"id": "D", "text": "Box"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Surface là composable Material cung cấp bề mặt với màu, shape và các đặc tính liên quan rồi chứa nội dung con. Box là primitive bố cục chồng lớp; dù có thể thêm background bằng Modifier, đáp án theo component Material được mô tả trong quiz vẫn là Surface.", "references": [{"url": "https://developer.android.com/develop/ui/compose/designsystems/material3", "title": "Compose · Material 3"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q9", "text": "Padding is an example of a ___", "type": "single", "options": [{"id": "A", "text": "Property"}, {"id": "B", "text": "Composable"}, {"id": "C", "text": "Attribute"}, {"id": "D", "text": "Modifier"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Modifier.padding(...) thay đổi khoảng cách quanh nội dung của composable. Thứ tự modifier có tác dụng: clickable().padding() có thể tạo vùng click khác padding().clickable(). Padding là modifier, không phải một composable riêng để bố trí các con.", "references": [{"url": "https://developer.android.com/develop/ui/compose/modifiers", "title": "Compose · Modifier"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p2-q10", "text": "Which of the following is false about Compose?", "type": "single", "options": [{"id": "A", "text": "The Empty Compose Activity template is used to create a simple app."}, {"id": "B", "text": "Layouts can be viewed in the Preview window, without actually running your app."}, {"id": "C", "text": "All elements and themes in a Compose app are contained in a Surface."}, {"id": "D", "text": "Themes, such as GreetingCardTheme allow you to style Composables."}], "answers": ["C"], "plain": true, "note": "", "explanation": "Theme có thể bao Surface và nhiều composable khác; không có yêu cầu mọi phần tử và mọi theme phải đặt bên trong Surface. Compose Preview có thể xem trước mà không khởi chạy toàn bộ app; theme cung cấp các giá trị thiết kế cho các component.", "references": [{"url": "https://developer.android.com/develop/ui/compose/designsystems/material3", "title": "Compose · Material 3"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-2/android-basics-compose-unit-1-pathway-2?hl=en", "title": "Google · Unit 1 · Pathway 2 · Đáp án đã kiểm chứng"}}]}, {"number": 3, "title": "Unit 1 · Pathway 3 · Build a basic layout", "questions": [{"id": "google-u1-p3-q1", "text": "What is Jetpack Compose?", "type": "single", "options": [{"id": "A", "text": "A Modern toolkit to develop Android UI"}, {"id": "B", "text": "Toolkit to design libraries"}, {"id": "C", "text": "Database Interface"}, {"id": "D", "text": "Plugin to build APK"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Compose là bộ công cụ UI Android theo hướng khai báo: mô tả giao diện tương ứng với state thay vì cập nhật từng View thủ công. Nó không phải một cơ sở dữ liệu hoặc plugin đóng gói APK.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q2", "text": "Composable functions are the basic building block of Compose.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Các composable nhỏ kết hợp thành cây UI lớn hơn và có thể tái sử dụng. Chúng là đơn vị mô tả giao diện, còn layout, modifier và state quyết định cách hiển thị cũng như thay đổi khi chạy.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q3", "text": "What annotation is used to annotate a Composable function?", "type": "single", "options": [{"id": "A", "text": "@Annotation"}, {"id": "B", "text": "@ComposableFunction"}, {"id": "C", "text": "@Composable"}, {"id": "D", "text": "@Preview"}], "answers": ["C"], "plain": true, "note": "", "explanation": "@Composable là annotation đánh dấu hàm Compose. @Preview cho phép công cụ tạo ảnh xem trước của một hàm phù hợp, nhưng hàm đó vẫn cần @Composable. @ComposableFunction trong lựa chọn không phải annotation chuẩn ở đây.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q4", "text": "The basic standard layout elements in Compose are:", "type": "multi", "options": [{"id": "A", "text": "Column"}, {"id": "B", "text": "Row"}, {"id": "C", "text": "Text"}, {"id": "D", "text": "Box"}], "answers": ["A", "B", "D"], "plain": true, "note": "", "explanation": "Column xếp theo chiều dọc, Row theo chiều ngang và Box xếp chồng hoặc căn các con trong một vùng. Text là thành phần hiển thị chữ; nó không thuộc ba primitive layout đang được hỏi.", "references": [{"url": "https://developer.android.com/develop/ui/compose/layouts/basics", "title": "Compose · Bố cục"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q5", "text": "What is the tool window for importing, creating, managing, and using resources in your app?", "type": "single", "options": [{"id": "A", "text": "Application Manager"}, {"id": "B", "text": "Resource Manager"}, {"id": "C", "text": "Resource Tool"}, {"id": "D", "text": "Layout Manager"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Resource Manager trong Android Studio giúp nhập và quản lý tài nguyên như drawable. Resource ID dùng trong mã nằm ở lớp R. Nó khác SDK Manager quản lý SDK và Device Manager quản lý thiết bị ảo.", "references": [{"url": "https://developer.android.com/guide/topics/resources/accessing-resources", "title": "Truy cập tài nguyên"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q6", "text": "Which class is an automatically generated class by Android that contains the IDs of all resources in the project.", "type": "single", "options": [{"id": "A", "text": "The Android class"}, {"id": "B", "text": "The Resource class"}, {"id": "C", "text": "The R Class"}, {"id": "D", "text": "The ResourceID class"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Công cụ build sinh lớp R với các nhóm như R.drawable, R.string và R.layout. Giá trị trong đó là ID tham chiếu tài nguyên, không phải nội dung ảnh hoặc chuỗi đã nạp. Không sửa thủ công file R sinh tự động.", "references": [{"url": "https://developer.android.com/guide/topics/resources/accessing-resources", "title": "Truy cập tài nguyên"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q7", "text": "Which function is used is to load a drawable image resource.", "type": "single", "options": [{"id": "A", "text": "The stringResource() function"}, {"id": "B", "text": "The painterResource() function"}, {"id": "C", "text": "The ImageResource() function"}, {"id": "D", "text": "The loadResource() function"}], "answers": ["B"], "plain": true, "note": "", "explanation": "painterResource(R.drawable.photo) tạo Painter từ drawable để dùng với Image. stringResource(...) nạp chuỗi. Ảnh từ mạng thường cần thư viện tải ảnh hoặc luồng xử lý khác, không truyền URL thay cho resource ID vào painterResource.", "references": [{"url": "https://developer.android.com/develop/ui/compose/graphics/images/loading", "title": "Compose · Nạp ảnh"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q8", "text": "What is the function parameter used to add accessibility text, used by talkback?", "type": "single", "options": [{"id": "A", "text": "accessibilityText"}, {"id": "B", "text": "contentText"}, {"id": "C", "text": "accessibilityDescription"}, {"id": "D", "text": "contentDescription"}], "answers": ["D"], "plain": true, "note": "", "explanation": "contentDescription cung cấp mô tả ngữ nghĩa để trình đọc màn hình đọc thay cho ảnh/icon có ý nghĩa. Ảnh chỉ để trang trí thường đặt null để tránh đọc thừa. Mô tả nên nói chức năng hoặc thông tin, không chỉ lặp “hình ảnh”.", "references": [{"url": "https://developer.android.com/develop/ui/compose/accessibility/semantics", "title": "Compose · Accessibility"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q9", "text": "The Box layout stacks the UI elements on top of one another.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Các con trong Box có thể chồng lên nhau; con khai báo sau thường vẽ trên con trước nếu không có điều chỉnh zIndex. Dùng alignment hoặc Modifier.align để định vị trong vùng Box, thay vì mặc định coi Box là một hàng hay cột.", "references": [{"url": "https://developer.android.com/develop/ui/compose/layouts/basics", "title": "Compose · Bố cục"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u1-p3-q10", "text": "What parameter is used to align the child element to the beginning of the parent?", "type": "single", "options": [{"id": "A", "text": "Alignment.End"}, {"id": "B", "text": "Alignment.Begin"}, {"id": "C", "text": "Alignment.Start"}, {"id": "D", "text": "Alignment.Top"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Start là cạnh bắt đầu theo layout direction: thường là trái với LTR và phải với RTL. Alignment.Start là căn theo chiều ngang trong API phù hợp; Alignment.Top là căn dọc, không cùng ý nghĩa.", "references": [{"url": "https://developer.android.com/develop/ui/compose/layouts/basics", "title": "Compose · Bố cục"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-1-pathway-3/android-basics-compose-unit-1-pathway-3?hl=en", "title": "Google · Unit 1 · Pathway 3 · Đáp án đã kiểm chứng"}}]}, {"number": 4, "title": "Unit 2 · Pathway 1 · Kotlin fundamentals", "questions": [{"id": "google-u2-p1-q1", "text": "The following code will print \"Divisible by 5\" if number is equal to 25 .\n\nif (number % 10 == 0) {\n  println(\"Divisible by 10\")\n} else if (number == 5) {\n  println(\"Divisible by 5\")\n}", "type": "single", "options": [{"id": "A", "text": "true"}, {"id": "B", "text": "false"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Với 25, điều kiện 25 % 10 == 0 sai, rồi 25 == 5 cũng sai. Không có else nên không in dòng nào. Muốn kiểm tra “chia hết cho 5” phải dùng number % 5 == 0, không dùng number == 5.", "references": [{"url": "https://kotlinlang.org/docs/control-flow.html", "title": "Kotlin · Phân nhánh"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q2", "text": "Which of the following conditions are satisfied when x = 5 ?", "type": "multi", "options": [{"id": "A", "text": "x == 5"}, {"id": "B", "text": "x in 1..5"}, {"id": "C", "text": "x is Int"}, {"id": "D", "text": "x % 5"}], "answers": ["A", "B", "C"], "plain": true, "note": "", "explanation": "x = 5 làm x == 5 đúng, khoảng 1..5 bao gồm cả hai đầu nên x in 1..5 đúng, và 5 có kiểu Int. x % 5 tạo số 0 chứ không phải điều kiện Boolean; muốn xét chia hết cần x % 5 == 0.", "references": [{"url": "https://kotlinlang.org/docs/control-flow.html", "title": "Kotlin · Phân nhánh"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q3", "text": "Which is not a basic concept of object-oriented programming", "type": "single", "options": [{"id": "A", "text": "Abstraction"}, {"id": "B", "text": "Readability"}, {"id": "C", "text": "Inheritance"}, {"id": "D", "text": "Polymorphism"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Abstraction mô tả phần cốt lõi, inheritance cho phép kế thừa, polymorphism cho phép cùng giao diện có nhiều cách triển khai. Readability là tính dễ đọc của mã, rất hữu ích nhưng không phải một khái niệm OOP cơ bản trong nhóm lựa chọn.", "references": [{"url": "https://kotlinlang.org/docs/inheritance.html", "title": "Kotlin · Kế thừa"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q4", "text": "Which are the four visibility modifiers in Kotlin?", "type": "single", "options": [{"id": "A", "text": "public , private , protected , abstract"}, {"id": "B", "text": "static , override , internal , external"}, {"id": "C", "text": "private , protected , public , internal"}, {"id": "D", "text": "public , protected , static , internal"}], "answers": ["C"], "plain": true, "note": "", "explanation": "public cho phép truy cập rộng; private giới hạn theo phạm vi khai báo; protected áp dụng cho thành viên trong lớp và lớp con; internal giới hạn theo module. abstract và override không phải visibility modifier.", "references": [{"url": "https://kotlinlang.org/docs/visibility-modifiers.html", "title": "Kotlin · Phạm vi truy cập"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q5", "text": "The ___ keyword is used to call a method from the parent class.", "type": "single", "options": [{"id": "A", "text": "this"}, {"id": "B", "text": "super"}, {"id": "C", "text": "parent"}, {"id": "D", "text": "self"}], "answers": ["B"], "plain": true, "note": "", "explanation": "super.method() gọi phần triển khai của lớp cha từ lớp con; this chỉ đối tượng hiện tại. Khi override một hàm, có thể gọi super để tái sử dụng hành vi cũ rồi thêm hành vi mới.", "references": [{"url": "https://kotlinlang.org/docs/inheritance.html", "title": "Kotlin · Kế thừa"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q6", "text": "A(n) ___ defines properties or methods that a class needs to implement.", "type": "single", "options": [{"id": "A", "text": "Delegate"}, {"id": "B", "text": "Generic type"}, {"id": "C", "text": "Interface"}, {"id": "D", "text": "Subclass"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Interface định nghĩa một hợp đồng gồm các thành viên mà lớp triển khai cần đáp ứng. Interface Kotlin có thể có phần triển khai mặc định của hàm; nó không phải luôn chỉ có tên hàm trống. Nó khác generic, vốn tham số hóa kiểu.", "references": [{"url": "https://kotlinlang.org/docs/interfaces.html", "title": "Kotlin · Interface"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q7", "text": "Which of the following is best represented by a nullable type?", "type": "single", "options": [{"id": "A", "text": "The number of followers (0 or more) in a social media app."}, {"id": "B", "text": "An optional profile picture."}, {"id": "C", "text": "A username that must be at least one character."}, {"id": "D", "text": "A unique ID given to every user."}], "answers": ["B"], "plain": true, "note": "", "explanation": "Ảnh đại diện tùy chọn có thể không tồn tại, nên kiểu nullable như String? cho URL ảnh thể hiện đúng ý nghĩa. Số người theo dõi bằng 0 vẫn là một giá trị Int hợp lệ, không đồng nghĩa dữ liệu vắng mặt.", "references": [{"url": "https://kotlinlang.org/docs/null-safety.html", "title": "Kotlin · Null safety"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q8", "text": "The ___ operator allows you to call a method only if the object is non-null.", "type": "single", "options": [{"id": "A", "text": "."}, {"id": "B", "text": "!!"}, {"id": "C", "text": "?:"}, {"id": "D", "text": "?."}], "answers": ["D"], "plain": true, "note": "", "explanation": "obj?.method() chỉ gọi method khi obj khác null và trả null nếu obj null. !! khẳng định khác null nên có thể gây NullPointerException; ?: cung cấp giá trị thay thế. Mỗi receiver nullable trong chuỗi cần được bảo vệ phù hợp.", "references": [{"url": "https://kotlinlang.org/docs/null-safety.html", "title": "Kotlin · Null safety"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q9", "text": "Which is not true of functions in Kotlin?", "type": "single", "options": [{"id": "A", "text": "A function can be changed to another data type, and vice versa."}, {"id": "B", "text": "A function can be returned from another function."}, {"id": "C", "text": "A function can take another function as a parameter."}, {"id": "D", "text": "A function has a data type, such as (Int) -> Unit ."}], "answers": ["A"], "plain": true, "note": "", "explanation": "Kotlin xem hàm là giá trị có kiểu hàm, có thể truyền làm argument hoặc trả từ hàm khác. Ví dụ (Int) -> Unit nhận Int và không trả giá trị hữu ích. Điều đó không tạo phép chuyển đổi tùy ý giữa hàm và mọi kiểu dữ liệu.", "references": [{"url": "https://kotlinlang.org/docs/lambdas.html", "title": "Kotlin · Hàm bậc cao và lambda"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p1-q10", "text": "A function literal is another name for a ___", "type": "single", "options": [{"id": "A", "text": "Function type"}, {"id": "B", "text": "Lambda expression"}, {"id": "C", "text": "Function reference"}, {"id": "D", "text": "Trailing lambda"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Trong các lựa chọn, lambda expression là function literal, như { x: Int -> x + 1 }. Function type mô tả kiểu của giá trị hàm, còn function reference như ::println tham chiếu hàm có sẵn. Kotlin cũng có anonymous function dạng fun(...) { ... }.", "references": [{"url": "https://kotlinlang.org/docs/lambdas.html", "title": "Kotlin · Hàm bậc cao và lambda"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-1/android-basics-compose-unit-2-pathway-1?hl=en", "title": "Google · Unit 2 · Pathway 1 · Đáp án đã kiểm chứng"}}]}, {"number": 5, "title": "Unit 2 · Pathway 2 · Add a button to an app", "questions": [{"id": "google-u2-p2-q1", "text": "Use a ___ Composable to display an image", "type": "single", "options": [{"id": "A", "text": "Button"}, {"id": "B", "text": "Text"}, {"id": "C", "text": "Image"}, {"id": "D", "text": "Icon"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Image là composable dùng để hiển thị Painter hoặc ImageBitmap. Icon thường dùng cho biểu tượng, còn Text để hiển thị chữ. Hãy cung cấp contentDescription phù hợp nếu ảnh truyền tải thông tin cho người dùng.", "references": [{"url": "https://developer.android.com/develop/ui/compose/graphics/images/loading", "title": "Compose · Nạp ảnh"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q2", "text": "Alignment.Center centers UI components both horizontally and vertically.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Alignment.Center mô tả căn giữa cả chiều ngang lẫn chiều dọc trong API nhận Alignment, ví dụ contentAlignment của Box. Các API một trục có giá trị riêng như Alignment.CenterHorizontally hoặc CenterVertically.", "references": [{"url": "https://developer.android.com/develop/ui/compose/layouts/basics", "title": "Compose · Bố cục"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q3", "text": "Composable functions can store an object in memory using the ___ composable", "type": "single", "options": [{"id": "A", "text": "remember"}, {"id": "B", "text": "Column"}, {"id": "C", "text": "Modifier"}, {"id": "D", "text": "@Composable"}], "answers": ["A"], "plain": true, "note": "", "explanation": "remember giữ kết quả tính tại vị trí đó qua recomposition, tránh tạo lại đối tượng mỗi lần. Nó mất khi composable rời composition và không tự lưu qua Activity recreation; rememberSaveable phù hợp một số state UI cần khôi phục.", "references": [{"url": "https://developer.android.com/develop/ui/compose/state", "title": "Compose · State"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q4", "text": "The debugger allows you to inspect variables when code execution has been suspended.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Khi chương trình dừng ở breakpoint, debugger cho xem biến, biểu thức và call stack trong ngữ cảnh đang dừng. Giá trị thuộc thread hoặc frame khác có thể cần chọn đúng frame; debugger không đồng nghĩa chương trình luôn chạy liên tục.", "references": [{"url": "https://developer.android.com/studio/debug", "title": "Android Studio · Debugger"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q5", "text": "By using ___ values in a composable function, variables can be made into observables that schedule a recomposition when their value is changed.", "type": "single", "options": [{"id": "A", "text": "remember"}, {"id": "B", "text": "Modifier"}, {"id": "C", "text": "@Composable"}, {"id": "D", "text": "mutableStateOf"}], "answers": ["D"], "plain": true, "note": "", "explanation": "mutableStateOf tạo một MutableState mà Compose quan sát các lần đọc. Khi value đổi theo chính sách so sánh của State, các vùng đọc nó có thể được lên lịch recomposition. remember chỉ giữ đối tượng; một biến mutable thường không tự trở thành state quan sát được.", "references": [{"url": "https://developer.android.com/develop/ui/compose/state", "title": "Compose · State"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q6", "text": "The ___ composable places its children in a vertical sequence.", "type": "single", "options": [{"id": "A", "text": "Row"}, {"id": "B", "text": "Box"}, {"id": "C", "text": "Column"}, {"id": "D", "text": "Modifier"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Column bố trí các con lần lượt theo trục dọc; Row bố trí theo trục ngang. Column không tự có cuộn: cần verticalScroll hoặc dùng LazyColumn cho danh sách phù hợp.", "references": [{"url": "https://developer.android.com/develop/ui/compose/layouts/basics", "title": "Compose · Bố cục"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p2-q7", "text": "The ___ debugger feature allows you to navigate back up the call stack.", "type": "single", "options": [{"id": "A", "text": "Step over"}, {"id": "B", "text": "Step out"}, {"id": "C", "text": "Step into"}, {"id": "D", "text": "Resume program"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Step out tiếp tục chạy đến khi thoát hàm hiện tại rồi dừng ở caller, giúp đi lên mức gọi phía ngoài. Step into đi vào hàm được gọi, Step over đi qua dòng hiện tại và Resume chạy tiếp đến điểm dừng kế tiếp.", "references": [{"url": "https://developer.android.com/studio/debug", "title": "Android Studio · Debugger"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-2/android-basics-compose-unit-2-pathway-2?hl=en", "title": "Google · Unit 2 · Pathway 2 · Đáp án đã kiểm chứng"}}]}, {"number": 6, "title": "Unit 2 · Pathway 3 · Interacting with UI and state", "questions": [{"id": "google-u2-p3-q1", "text": "Jetpack Compose runs your composables for the first time, during ___ it will keep track of the composables that you call to describe your UI.", "type": "single", "options": [{"id": "A", "text": "Initial composition"}, {"id": "B", "text": "Recomposition"}, {"id": "C", "text": "State change"}, {"id": "D", "text": "App termination"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Initial composition là lần Compose chạy các composable ban đầu để tạo mô tả UI và ghi nhận quan hệ giữa chúng. Các cập nhật tiếp theo do dữ liệu liên quan thay đổi thuộc recomposition, không gọi là initial composition nữa.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q2", "text": "The only way to modify a Composition is through recomposition.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Theo mô hình của bài học, thay đổi mô tả UI đã có được thực hiện qua recomposition thay vì sửa cây widget thủ công. Việc state thay đổi là nguyên nhân có thể yêu cầu cập nhật; nó không đồng nghĩa mọi composable đều phải chạy lại.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q3", "text": "___ is when Jetpack Compose re-executes the composables that may have changed in response to data changes.", "type": "single", "options": [{"id": "A", "text": "Initial composition"}, {"id": "B", "text": "Recomposition"}, {"id": "C", "text": "State change"}, {"id": "D", "text": "App termination"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Recomposition thực thi lại các composable cần thiết khi đầu vào hoặc state chúng đọc thay đổi. Compose có thể bỏ qua phần không bị ảnh hưởng; không nên dựa vào việc một composable sẽ chạy đúng số lần cố định.", "references": [{"url": "https://developer.android.com/develop/ui/compose/mental-model", "title": "Mô hình Compose"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q4", "text": "___ in an application is any value that can change over time.", "type": "single", "options": [{"id": "A", "text": "State"}, {"id": "B", "text": "value"}, {"id": "C", "text": "valueChange"}, {"id": "D", "text": "StateValue"}], "answers": ["A"], "plain": true, "note": "", "explanation": "State là dữ liệu thay đổi theo thời gian, như nội dung ô nhập, số đếm hoặc mục được chọn. UI nên phản ánh state hiện tại. Không phải mọi biến đều cần là MutableState; lựa chọn cơ chế phụ thuộc nơi quản lý và cách quan sát.", "references": [{"url": "https://developer.android.com/develop/ui/compose/state", "title": "Compose · State"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q5", "text": "___ is a pattern of moving state up to make a component stateless.", "type": "single", "options": [{"id": "A", "text": "State change"}, {"id": "B", "text": "State hoisting"}, {"id": "C", "text": "Hoist composition"}, {"id": "D", "text": "Recomposition"}], "answers": ["B"], "plain": true, "note": "", "explanation": "State hoisting chuyển state lên caller và truyền xuống giá trị cùng callback, ví dụ value và onValueChange. Nhờ vậy composable con dễ tái sử dụng và kiểm thử; state có một nguồn quản lý rõ ràng thay vì nhiều bản sao không đồng bộ.", "references": [{"url": "https://developer.android.com/develop/ui/compose/state", "title": "Compose · State"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q6", "text": "Which KeyboardAction property is used to move the focus to the next composable?", "type": "single", "options": [{"id": "A", "text": "onDone"}, {"id": "B", "text": "onNext"}, {"id": "C", "text": "onGo"}, {"id": "D", "text": "onSend"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Trong KeyboardActions, onNext nhận hành động IME Next. Khi tự khai báo callback, có thể gọi focusManager.moveFocus(FocusDirection.Down) để chuyển focus phù hợp. Chỉ đặt tên onNext không có nghĩa mọi đoạn callback tùy ý sẽ tự chuyển focus; ImeAction.Next cũng cần cấu hình thích hợp.", "references": [{"url": "https://developer.android.com/develop/ui/compose/touch-input/focus/request-focus", "title": "Compose · Focus"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q7", "text": "Which of the following Kotlin functions is used to round up a Double or Float?", "type": "single", "options": [{"id": "A", "text": "kotlin.math.ceilUp()"}, {"id": "B", "text": "kotlin.math.ceil()"}, {"id": "C", "text": "kotlin.math.roundDown()"}, {"id": "D", "text": "kotlin.math.roundUp()"}], "answers": ["B"], "plain": true, "note": "", "explanation": "kotlin.math.ceil làm tròn về số nguyên gần nhất theo hướng dương vô cùng, nhưng kiểu trả về vẫn là Double hoặc Float tương ứng. Ví dụ ceil(2.1) = 3.0 và ceil(-2.1) = -2.0. Nó khác round và phép đổi .toInt() cắt phần thập phân.", "references": [{"url": "https://kotlinlang.org/api/core/kotlin-stdlib/kotlin.math/ceil.html", "title": "Kotlin · ceil"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q8", "text": "Layout Inspector is a tool in Jetpack Compose that allows you to inspect a Compose layout inside a running app in an emulator or physical device.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Layout Inspector xem cây giao diện của ứng dụng đang chạy trên thiết bị hoặc emulator hỗ trợ, gồm thông tin layout Compose. Nó khác Compose Preview là công cụ xem trước, và khác debugger dùng để dừng/đi từng dòng mã.", "references": [{"url": "https://developer.android.com/studio/debug/layout-inspector", "title": "Layout Inspector"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q9", "text": "UI tests are stored in the ___ directory.", "type": "single", "options": [{"id": "A", "text": "main"}, {"id": "B", "text": "androidTest"}, {"id": "C", "text": "test"}, {"id": "D", "text": "res"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Instrumented UI tests thường đặt tại src/androidTest và chạy trên thiết bị/emulator. Local JVM tests thường ở src/test. Đây là quy ước source set của dự án Android, không phải mọi loại kiểm thử giao diện trong mọi framework đều bắt buộc dùng cùng thư mục.", "references": [{"url": "https://developer.android.com/training/testing/fundamentals", "title": "Kiểm thử Android"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u2-p3-q10", "text": "Local tests and UI tests should be annotated with the ___ annotation.", "type": "single", "options": [{"id": "A", "text": "@VisibleForTesting"}, {"id": "B", "text": "@Preview"}, {"id": "C", "text": "@Test"}, {"id": "D", "text": "@Composable"}], "answers": ["C"], "plain": true, "note": "", "explanation": "@Test đánh dấu phương thức kiểm thử cho JUnit runner phù hợp. @Preview phục vụ xem trước UI, @Composable đánh dấu hàm Compose và @VisibleForTesting mô tả ý định về phạm vi truy cập, không thay thế @Test.", "references": [{"url": "https://developer.android.com/training/testing/fundamentals", "title": "Kiểm thử Android"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-2-pathway-3/android-basics-compose-unit-2-pathway-3?hl=en", "title": "Google · Unit 2 · Pathway 3 · Đáp án đã kiểm chứng"}}]}, {"number": 7, "title": "Unit 3 · Pathway 1 · More Kotlin fundamentals", "questions": [{"id": "google-u3-p1-q1", "text": "Which of the following is a valid way to define a data class in Kotlin?", "type": "single", "options": [{"id": "A", "text": "data class Person(val name: String, val age: Int)"}, {"id": "B", "text": "class Person(val name: String, val age: Int): data"}, {"id": "C", "text": "class Person (val name: String, val age: Int)"}, {"id": "D", "text": "data class Person{val name: String, val age: Int}"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Dùng data class với primary constructor có ít nhất một tham số, và các tham số đó phải là val hoặc var. Kotlin sinh các hàm như equals, hashCode, toString, componentN và copy dựa trên các thuộc tính trong primary constructor.", "references": [{"url": "https://kotlinlang.org/docs/data-classes.html", "title": "Kotlin · Data class"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q2", "text": "When using a sealed class, all direct subclasses must be in the same package.", "type": "single", "options": [{"id": "A", "text": "true"}, {"id": "B", "text": "false"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Các lớp con trực tiếp của sealed class phải ở cùng package và cùng module; còn có quy tắc bổ sung với multiplatform. Điều này giới hạn tập nhánh để when có thể kiểm tra tính đầy đủ. Không yêu cầu mọi lớp con gián tiếp đều nằm trong cùng một file.", "references": [{"url": "https://kotlinlang.org/docs/sealed-classes.html", "title": "Kotlin · Sealed class"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q3", "text": "When using generics, the generic data type goes inside ___.", "type": "single", "options": [{"id": "A", "text": "[]"}, {"id": "B", "text": "{}"}, {"id": "C", "text": "()"}, {"id": "D", "text": "<>"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Tham số kiểu generic nằm trong < >, như class Box<T> hoặc List<String>. Dấu ( ) dùng cho tham số/argument hàm và { } dùng cho thân khối hoặc lambda. Compiler đôi khi suy ra được argument kiểu nên không cần viết rõ khi gọi.", "references": [{"url": "https://kotlinlang.org/docs/generics.html", "title": "Kotlin · Generics"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q4", "text": "A(n) ___ class is useful when you have a fixed set of values.", "type": "single", "options": [{"id": "A", "text": "enum"}, {"id": "B", "text": "sealed"}, {"id": "C", "text": "data"}, {"id": "D", "text": "inherited"}], "answers": ["A"], "plain": true, "note": "", "explanation": "enum class biểu diễn một tập instance hằng định danh cố định, như Direction.NORTH và SOUTH. sealed class phù hợp một tập loại con có thể mang cấu trúc dữ liệu khác nhau; data class chủ yếu mô hình hóa dữ liệu.", "references": [{"url": "https://kotlinlang.org/docs/enum-classes.html", "title": "Kotlin · Enum"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q5", "text": "To create a list object that has the ability to change its size, you would call ___.", "type": "single", "options": [{"id": "A", "text": "modifiableListOf()"}, {"id": "B", "text": "immutableListOf()"}, {"id": "C", "text": "listOf()"}, {"id": "D", "text": "mutableListOf()"}], "answers": ["D"], "plain": true, "note": "", "explanation": "mutableListOf(...) tạo MutableList có thao tác add/remove để đổi kích thước. listOf(...) cung cấp giao diện List chỉ đọc, không có add/remove qua giao diện đó; “read-only” không nhất thiết chứng minh đối tượng nền bất biến tuyệt đối.", "references": [{"url": "https://kotlinlang.org/docs/collections-overview.html", "title": "Kotlin · Collection"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q6", "text": "Which of the following are higher-order functions?", "type": "multi", "options": [{"id": "A", "text": "map"}, {"id": "B", "text": "arrangeBy"}, {"id": "C", "text": "filter"}, {"id": "D", "text": "forEach"}], "answers": ["A", "C", "D"], "plain": true, "note": "", "explanation": "map biến đổi mỗi phần tử, filter giữ các phần tử thỏa điều kiện và forEach thực hiện hành động cho từng phần tử; cả ba nhận hàm/lambda làm tham số. arrangeBy không phải hàm chuẩn trong nhóm này; để sắp xếp có sortedBy hoặc sortBy tùy loại collection.", "references": [{"url": "https://kotlinlang.org/docs/collection-transformations.html", "title": "Kotlin · Phép biến đổi collection"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q7", "text": "Given the following line of code, which of the following commands will print Blue ? (Hint: If you are not sure, try running the code in the Kotlin Playground.)\n\nval colors = listOf(\"Red\", \"Green\", \"Blue\")", "type": "multi", "options": [{"id": "A", "text": "println(colors[2])"}, {"id": "B", "text": "println(colors.get(2))"}, {"id": "C", "text": "println(colors.contains(2))"}, {"id": "D", "text": "println(colors.getOrDefaultValue(index = 2, defaultValue = 10))"}], "answers": ["A", "B"], "plain": true, "note": "", "explanation": "List dùng chỉ số bắt đầu từ 0, nên vị trí 2 là phần tử thứ ba \"Blue\". colors[2] tương đương colors.get(2). contains kiểm tra sự hiện diện của một giá trị chứ không đọc theo chỉ số; getOrDefaultValue trong lựa chọn không phải API List chuẩn đó.", "references": [{"url": "https://kotlinlang.org/docs/collections-overview.html", "title": "Kotlin · Collection"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q8", "text": "The programming concept of a class that has only one instance is called a ___.", "type": "single", "options": [{"id": "A", "text": "Uniqueness"}, {"id": "B", "text": "Singleton"}, {"id": "C", "text": "Mono-object"}, {"id": "D", "text": "Lambda"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Singleton là mẫu có một instance được dùng chung. Trong Kotlin, object declaration là cách khai báo singleton quen thuộc; class thông thường vẫn tạo được nhiều instance nếu constructor cho phép. Lambda là giá trị hàm, không phải khái niệm singleton.", "references": [{"url": "https://kotlinlang.org/docs/object-declarations.html", "title": "Kotlin · Singleton"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q9", "text": "Which of the following statements is true regarding sets and maps?", "type": "single", "options": [{"id": "A", "text": "A set must contain distinct values and a map’s keys must be distinct."}, {"id": "B", "text": "A set must contain distinct values and a map’s keys can contain duplicates."}, {"id": "C", "text": "A set can contain duplicate values and a map’s values can contain duplicate values."}, {"id": "D", "text": "A set can contain duplicate values and a map’s keys must be distinct."}], "answers": ["A"], "plain": true, "note": "", "explanation": "Set chứa các phần tử phân biệt; Map có key phân biệt nhưng value có thể lặp. Thêm lại key vào mutable map thường cập nhật value tương ứng, không tạo thêm hai mục có cùng key.", "references": [{"url": "https://kotlinlang.org/docs/collections-overview.html", "title": "Kotlin · Collection"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p1-q10", "text": "If you have a variable named records , which is a collection, to determine the number of items it contains, you can call ___.", "type": "single", "options": [{"id": "A", "text": "records.length"}, {"id": "B", "text": "records.quantity"}, {"id": "C", "text": "len(records)"}, {"id": "D", "text": "records.size"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Thuộc tính size cho biết số phần tử của Collection, như list, set hoặc map. length thường dùng cho String hoặc CharSequence. size không phải index cuối: list có 3 phần tử thì index hợp lệ là 0, 1, 2.", "references": [{"url": "https://kotlinlang.org/docs/collections-overview.html", "title": "Kotlin · Collection"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-1/android-basics-compose-unit-3-pathway-1?hl=en", "title": "Google · Unit 3 · Pathway 1 · Đáp án đã kiểm chứng"}}]}, {"number": 8, "title": "Unit 3 · Pathway 2 · Build a scrollable list", "questions": [{"id": "google-u3-p2-q1", "text": "Adaptive launcher icons for Android apps consist of a foreground and background vector drawable.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Google chấm True theo bài thực hành tạo foreground/background bằng vector drawable. Về API tổng quát, adaptive icon nhận drawable cho các lớp, không bắt buộc tất cả phải là vector. Launcher áp mask lên các lớp; phiên bản mới còn có thể dùng lớp monochrome.", "references": [{"url": "https://developer.android.com/develop/ui/compose/system/icon_design_adaptive", "title": "Adaptive icon"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q2", "text": "When building a UI that requires a scrolling list with a variable number of items, which Composable should you use?", "type": "single", "options": [{"id": "A", "text": "Column"}, {"id": "B", "text": "Row"}, {"id": "C", "text": "LazyColumn"}, {"id": "D", "text": "Card"}], "answers": ["C"], "plain": true, "note": "", "explanation": "LazyColumn chỉ compose/bố trí các mục cần thiết khi hiển thị, phù hợp danh sách dọc cuộn lớn hoặc có số lượng thay đổi. Column tạo tất cả con và không tự cuộn. Lazy không có nghĩa dữ liệu không cần tải: việc nạp dữ liệu vẫn là trách nhiệm khác.", "references": [{"url": "https://developer.android.com/develop/ui/compose/lists", "title": "Compose · Lazy list và grid"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q3", "text": "What file type is used for the launcher icon foreground and background vectors?", "type": "single", "options": [{"id": "A", "text": ".txt"}, {"id": "B", "text": ".jpg"}, {"id": "C", "text": ".png"}, {"id": "D", "text": ".xml"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Vector drawable được mô tả bằng XML, bao gồm các đường path và màu. PNG/JPG là bitmap chứ không phải định dạng vector XML của Android. adaptive-icon cũng được khai báo bằng XML để tham chiếu các lớp icon.", "references": [{"url": "https://developer.android.com/develop/ui/compose/system/icon_design_adaptive", "title": "Adaptive icon"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q4", "text": "Which Composable should you use to create a vertically scrollable grid with an undetermined number of items?", "type": "single", "options": [{"id": "A", "text": "LazyColumn"}, {"id": "B", "text": "LazyVerticalGrid"}, {"id": "C", "text": "LazyHorizontalGrid"}, {"id": "D", "text": "Row"}], "answers": ["B"], "plain": true, "note": "", "explanation": "LazyVerticalGrid hiển thị các ô dạng lưới có cuộn dọc và tạo nội dung theo nhu cầu. LazyHorizontalGrid cuộn ngang, còn LazyColumn là danh sách một chiều dọc. Chọn số cột cố định hoặc adaptive theo yêu cầu thiết kế.", "references": [{"url": "https://developer.android.com/develop/ui/compose/lists", "title": "Compose · Lazy list và grid"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q5", "text": "The Column composable is not a good option for a list of items of unknown quantity because ___.", "type": "single", "options": [{"id": "A", "text": "It can only hold a small, finite number of predefined items"}, {"id": "B", "text": "It arranges items vertically"}, {"id": "C", "text": "It provides scrolling by default without any additional code"}, {"id": "D", "text": "It can add content on demand"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Google chấm phương án đầu trong bản gốc, nhưng diễn đạt rằng Column “chỉ chứa được ít phần tử định sẵn” là giản lược. Column vẫn có thể tạo nội dung từ danh sách động; điểm yếu là tạo tất cả con và không tự cuộn. LazyColumn phù hợp hơn khi danh sách lớn hoặc không biết trước kích thước.", "references": [{"url": "https://developer.android.com/develop/ui/compose/lists", "title": "Compose · Lazy list và grid"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q6", "text": "The ___ method is used to add content to a LazyColumn Composable.", "type": "single", "options": [{"id": "A", "text": "painterResource()"}, {"id": "B", "text": "Modifier.padding()"}, {"id": "C", "text": "items()"}, {"id": "D", "text": "onCreate()"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Trong content DSL của LazyColumn, items(list) hoặc items(count) thêm nhiều mục; item { ... } thêm một mục riêng. Đây không phải Modifier hay hàm nạp ảnh. Dùng key ổn định khi phù hợp giúp giữ state mục khi danh sách thay đổi.", "references": [{"url": "https://developer.android.com/develop/ui/compose/lists", "title": "Compose · Lazy list và grid"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q7", "text": "Which Composable arranges items horizontally?", "type": "single", "options": [{"id": "A", "text": "Column"}, {"id": "B", "text": "Card"}, {"id": "C", "text": "Image"}, {"id": "D", "text": "Row"}], "answers": ["D"], "plain": true, "note": "", "explanation": "Row bố trí các phần tử theo chiều ngang; dùng horizontalArrangement và verticalAlignment để điều chỉnh. Card là container Material, không tự mang ý nghĩa xếp mọi con thành một hàng trong tất cả API.", "references": [{"url": "https://developer.android.com/develop/ui/compose/layouts/basics", "title": "Compose · Bố cục"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p2-q8", "text": "Which Composable arranges items vertically?", "type": "single", "options": [{"id": "A", "text": "Column"}, {"id": "B", "text": "Card"}, {"id": "C", "text": "Image"}, {"id": "D", "text": "Row"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Column bố trí các phần tử theo chiều dọc; dùng verticalArrangement và horizontalAlignment để điều chỉnh. Image chỉ hiển thị ảnh, còn Row có trục bố trí chính là ngang.", "references": [{"url": "https://developer.android.com/develop/ui/compose/layouts/basics", "title": "Compose · Bố cục"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-2/android-basics-compose-unit-3-pathway-2?hl=en", "title": "Google · Unit 3 · Pathway 2 · Đáp án đã kiểm chứng"}}]}, {"number": 9, "title": "Unit 3 · Pathway 3 · Build beautiful apps", "questions": [{"id": "google-u3-p3-q1", "text": "Animations in your Android app can:", "type": "single", "options": [{"id": "A", "text": "Add visual cues about what's going on in your app."}, {"id": "B", "text": "Add a polished look to your app."}, {"id": "C", "text": "Help the user see what changed."}, {"id": "D", "text": "All of the above."}], "answers": ["D"], "plain": true, "note": "", "explanation": "Animation có thể cho biết hành động đang diễn ra, làm rõ thay đổi UI và tạo chuyển động mượt hơn, nên chọn All of the above. Chuyển động vẫn cần có mục đích và cân nhắc khả năng tiếp cận; thêm nhiều animation không tự bảo đảm UX tốt.", "references": [{"url": "https://developer.android.com/develop/ui/compose/animation/customize", "title": "Compose · Animation"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q2", "text": "Spring animation is based on:", "type": "single", "options": [{"id": "A", "text": "Start and end values over the specified duration."}, {"id": "B", "text": "Damping ratio and stiffness."}, {"id": "C", "text": "Snapshot values specified at different timestamps."}, {"id": "D", "text": "Interpolation between two keyframe values."}], "answers": ["B"], "plain": true, "note": "", "explanation": "Spring là mô hình vật lý điều khiển chủ yếu bởi dampingRatio và stiffness, không phải chỉ thời lượng cố định. Damping ảnh hưởng dao động/tắt dần, stiffness ảnh hưởng độ cứng và nhịp đáp ứng. tween và keyframes là các cách mô tả chuyển động khác.", "references": [{"url": "https://developer.android.com/develop/ui/compose/animation/customize", "title": "Compose · Animation"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q3", "text": "Spring animation is a physics-based animation driven by spring force.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Spring animation mô phỏng lực lò xo đưa giá trị về mục tiêu. Khi đổi mục tiêu giữa chừng, nó có thể tiếp tục dựa trên trạng thái/vận tốc hiện tại, khác cách nội suy chỉ dựa trên mốc thời gian cố định.", "references": [{"url": "https://developer.android.com/develop/ui/compose/animation/customize", "title": "Compose · Animation"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q4", "text": "In the Material theming, the ___ color is the color displayed most frequently across your app's screens and components.", "type": "single", "options": [{"id": "A", "text": "primary"}, {"id": "B", "text": "secondary"}, {"id": "C", "text": "surface"}, {"id": "D", "text": "background"}], "answers": ["A"], "plain": true, "note": "", "explanation": "primary là đáp án theo cách mô tả vai trò màu thương hiệu của quiz. Không nên hiểu thành quy tắc đếm pixel rằng primary luôn chiếm diện tích lớn nhất: surface/background có thể phủ phần lớn màn hình. Material 3 dùng nhiều vai trò màu với màu nội dung tương ứng để giữ tương phản.", "references": [{"url": "https://developer.android.com/develop/ui/compose/designsystems/material3", "title": "Compose · Material 3"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q5", "text": "The following file is used to define shapes of components in Compose.", "type": "single", "options": [{"id": "A", "text": "Theme.kt"}, {"id": "B", "text": "Color.kt"}, {"id": "C", "text": "Shape.kt"}, {"id": "D", "text": "Colors.kt"}], "answers": ["C"], "plain": true, "note": "", "explanation": "Shape.kt là tên file quy ước trong cấu trúc dự án bài học để khai báo shape. Kotlin không bắt buộc phải dùng tên file này; cấu hình shape có thể đặt ở file khác hoặc dùng giá trị mặc định của MaterialTheme. Đáp án cần hiểu theo template của bài.", "references": [{"url": "https://developer.android.com/develop/ui/compose/designsystems/material3", "title": "Compose · Material 3"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q6", "text": "You can only have one @Preview composable", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["B"], "plain": true, "note": "", "explanation": "Có thể tạo nhiều hàm @Preview hoặc áp dụng nhiều preview để xem nhiều kích thước, theme và cấu hình. Preview phục vụ công cụ Android Studio, không phải giới hạn số màn hình trong ứng dụng. Hàm preview gọi UI Compose phù hợp với các yêu cầu của công cụ.", "references": [{"url": "https://developer.android.com/develop/ui/compose/tooling/previews", "title": "Compose · Preview"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q7", "text": "A hex color code starts with a pound (#) character, and is followed by six letters and/or numbers that represent the red, green, and blue (RGB) components of that color.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Dạng #RRGGBB dùng hai chữ số hệ 16 cho mỗi kênh đỏ, lục, lam, ví dụ #FF0000 là đỏ. Đây là một định dạng RGB phổ biến chứ không phải mọi cách viết màu; Android còn hỗ trợ alpha. Trong Kotlin thường gặp Color(0xFFFF0000), với FF đầu là độ đục alpha.", "references": [{"url": "https://developer.android.com/reference/android/graphics/Color", "title": "Mã màu Android"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q8", "text": "The ___ file is the file that holds all the information about the theme of the app which is defined through color, shape, and typography.", "type": "single", "options": [{"id": "A", "text": "Theme.kt"}, {"id": "B", "text": "Color.kt"}, {"id": "C", "text": "Shape.kt"}, {"id": "D", "text": "Colors.kt"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Theme.kt thường kết hợp color scheme, typography và shapes rồi truyền vào MaterialTheme. Tên file là quy ước tổ chức mã, không phải một file cấu hình mà Android bắt buộc nhận đúng tên. Color.kt và Shape.kt có thể chứa từng nhóm giá trị riêng.", "references": [{"url": "https://developer.android.com/develop/ui/compose/designsystems/material3", "title": "Compose · Material 3"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q9", "text": "___  creates contrast between the Card and the background by adding a shadow to make the app look more realistic and visually interesting?", "type": "single", "options": [{"id": "A", "text": "Elevation"}, {"id": "B", "text": "Shape"}, {"id": "C", "text": "Color"}, {"id": "D", "text": "Theme"}], "answers": ["A"], "plain": true, "note": "", "explanation": "Elevation thể hiện độ nổi của bề mặt, có thể tạo bóng để phân biệt Card với nền. Material 3 còn phân biệt shadow elevation và tonal elevation; không phải mọi thay đổi độ nổi chỉ là một bóng đen cố định. Shape đổi hình dạng, không phải khái niệm độ cao này.", "references": [{"url": "https://developer.android.com/develop/ui/compose/designsystems/material3", "title": "Compose · Material 3"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q10", "text": "What are reasons that someone may use Dark Theme on their device?", "type": "single", "options": [{"id": "A", "text": "It can reduce power usage by a significant amount (depending on the device’s screen technology)."}, {"id": "B", "text": "It improves visibility for users with low vision and those who are sensitive to bright light."}, {"id": "C", "text": "It makes it easier for anyone to use a device in a low-light environment."}, {"id": "D", "text": "All of the above."}], "answers": ["D"], "plain": true, "note": "", "explanation": "Dark theme có thể hỗ trợ người nhạy ánh sáng hoặc môi trường tối và tiết kiệm điện tùy công nghệ màn hình, nhất là OLED. Không bảo đảm mọi người đều đọc dễ hơn và mọi màn hình đều tiết kiệm như nhau; vẫn cần màu sắc/tương phản phù hợp. Đáp án của quiz là cả ba lý do.", "references": [{"url": "https://developer.android.com/develop/ui/views/theming/darktheme", "title": "Dark theme"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q11", "text": "TalkBack allows a user to navigate an app using switches instead of the touchscreen.", "type": "single", "options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}], "answers": ["B"], "plain": true, "note": "", "explanation": "TalkBack là screen reader, đọc nội dung và hỗ trợ điều hướng bằng phản hồi giọng nói/cử chỉ. Dùng công tắc bên ngoài để điều khiển là Switch Access. Hai công cụ hỗ trợ các nhu cầu khác nhau nên phát biểu gán chức năng switch cho TalkBack là sai.", "references": [{"url": "https://support.google.com/accessibility/android/answer/6122836", "title": "Google · Switch Access"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}, {"id": "google-u3-p3-q12", "text": "Which attribute allows TalkBack to speak a meaningful representation of an image or icon?", "type": "single", "options": [{"id": "A", "text": "elevation"}, {"id": "B", "text": "shape"}, {"id": "C", "text": "contentDescription"}, {"id": "D", "text": "style"}], "answers": ["C"], "plain": true, "note": "", "explanation": "contentDescription giúp TalkBack nói ý nghĩa ảnh/icon có thông tin hoặc hành động. Hãy mô tả tác dụng như “Mở tìm kiếm” thay vì chỉ “biểu tượng kính lúp”. Với ảnh trang trí, đặt mô tả null khi phù hợp để tránh thông tin gây nhiễu.", "references": [{"url": "https://developer.android.com/develop/ui/compose/accessibility/semantics", "title": "Compose · Accessibility"}], "reviewedOn": "2026-11-10", "source": {"url": "https://developer.android.com/courses/quizzes/android-basics-compose-unit-3-pathway-3/android-basics-compose-unit-3-pathway-3?hl=en", "title": "Google · Unit 3 · Pathway 3 · Đáp án đã kiểm chứng"}}]}];
